_LEGACY_CODE = '"""\ntrain_path_B.py  —  Path B: Two-stage detect + classify pipeline.\n\nStage 1: YOLO detector (reuses best Path A weights) — localises objects\nStage 2: Crop classifier (ResNet-50 or ViT-B/16) — refines class prediction\n\nTwo crop-sourcing modes:\n  --use_yolo_crops   Run the YOLO detector on every image and classify the\n                     detected boxes (true apples-to-apples comparison with\n                     evaluate_path_B_combined.py).  Crops are cached to\n                     --crop_cache_dir on first run.\n  (default)          Load the 224x224 GT crops pre-generated by preprocess.py\n                     (faster, but uses ground-truth boxes, not detected ones).\n\nUsage — YOLO-crop mode (recommended, matches evaluation protocol):\n  conda activate litter_AB\n  python train_path_B.py \\\n      --detector_weights ~/runs/path_A_4cls/yolov8m/weights/best.pt \\\n      --crops_dir        ~/processed_4cls \\\n      --output           ~/runs/path_B \\\n      --classifiers      resnet50 vit_b16_scratch vit_b16_imagenet \\\n      --epochs           50 \\\n      --batch            32 \\\n      --device           0 \\\n      --use_yolo_crops \\\n      --det_conf         0.25 \\\n      --crop_cache_dir   ~/runs/path_B/crop_cache\n\nUsage — GT-crop mode (fast baseline):\n  python train_path_B.py \\\n      --detector_weights ~/runs/path_A_4cls/yolov8m/weights/best.pt \\\n      --crops_dir        ~/processed_4cls \\\n      --output           ~/runs/path_B \\\n      --classifiers      resnet50 vit_b16_scratch vit_b16_imagenet \\\n      --epochs           50 --batch 32 --device 0\n"""\n\nimport argparse\nimport json\nimport time\nfrom pathlib import Path\n\nimport mlflow\nimport numpy as np\nimport pandas as pd\nimport torch\nimport torch.nn as nn\nimport torch.optim as optim\nimport yaml\nfrom PIL import Image\nfrom torch.utils.data import DataLoader, Dataset\nfrom torchvision import transforms\nfrom torchvision.io import read_image\nfrom tqdm import tqdm\nimport timm\nfrom sklearn.metrics import (\n    precision_score, recall_score, f1_score,\n    average_precision_score, confusion_matrix,\n)\nimport matplotlib.pyplot as plt\nfrom sklearn.metrics import ConfusionMatrixDisplay\n\n# ─────────────────────────────────────────────────────────────────────────────\n# CONSTANTS\n# ─────────────────────────────────────────────────────────────────────────────\n\nCOARSE_CLASSES = ["plastic", "paper", "metal", "other"]\nNUM_CLASSES    = len(COARSE_CLASSES)\nCROP_SIZE      = 224\n\nCLASSIFIER_REGISTRY = {\n    # B1: ResNet-50 — strong ImageNet CNN baseline\n    "resnet50":         ("resnet50.a1_in1k",                          True),\n    # B2: ViT-B/16 random init — architecture value without pretraining\n    "vit_b16_scratch":  ("vit_base_patch16_224",                      False),\n    # B3: ViT-B/16 ImageNet21k pretrained — large-scale pretraining value\n    "vit_b16_imagenet": ("vit_base_patch16_224.augreg_in21k_ft_in1k", True),\n}\n\n# ─────────────────────────────────────────────────────────────────────────────\n# YOLO-CROP DATASET\n# Extracts 224×224 crops from detected YOLO boxes rather than GT boxes.\n# Matches the evaluation protocol used in evaluate_path_B_combined.py.\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass YOLOCropDataset(Dataset):\n    """\n    Runs a frozen YOLO detector over every image in {split}/path_B/images,\n    matches each detected box to the nearest GT box (IoU ≥ 0.5) to assign a\n    label, crops and resizes to 224×224, then caches to disk.\n\n    On subsequent epochs the cached crops are loaded directly (fast path).\n\n    Args:\n        data_root:  processed_4cls root (contains train/val/test/path_B)\n        split:      "train" | "val" | "test"\n        detector:   Ultralytics YOLO model (frozen, for inference only)\n        device:     inference device string, e.g. "0" or "cpu"\n        conf:       YOLO detection confidence threshold (default 0.25)\n        transform:  torchvision transform applied after crop\n        cache_dir:  if provided, crops are saved here and reloaded on re-use\n    """\n\n    def __init__(\n        self,\n        data_root: Path,\n        split:     str,\n        detector,\n        device:    str,\n        conf:      float = 0.25,\n        transform=None,\n        cache_dir: Path = None,\n    ):\n        self.transform = transform\n        self.samples   = []          # [(crop_tensor_or_path, label)]\n        self._use_cache = cache_dir is not None\n\n        img_dir = Path(data_root) / split / "path_B" / "images"\n        lbl_dir = Path(data_root) / split / "path_B" / "labels"\n        assert img_dir.exists(), f"Image dir not found: {img_dir}"\n\n        cache_root = Path(cache_dir) / split if cache_dir else None\n        if cache_root and cache_root.exists():\n            # ── fast path: load from cache ────────────────────────────────\n            print(f"  [{split}] Loading YOLOCropDataset from cache: {cache_root}")\n            for cls_dir in sorted(cache_root.iterdir()):\n                if not cls_dir.is_dir():\n                    continue\n                try:\n                    cls_idx = int(cls_dir.name)\n                except ValueError:\n                    continue\n                for p in cls_dir.glob("*.jpg"):\n                    self.samples.append((p, cls_idx))\n            print(f"  [{split}] {len(self.samples)} cached crops loaded")\n            return\n\n        # ── slow path: detect + crop + (optionally cache) ─────────────────\n        print(f"\\n  [{split}] Building YOLOCropDataset via YOLO detection…")\n        img_paths = sorted(img_dir.glob("*.jpg"))\n        n_matched = 0\n        n_skipped = 0\n\n        if cache_root:\n            cache_root.mkdir(parents=True, exist_ok=True)\n\n        for img_path in tqdm(img_paths, desc=f"  [{split}] YOLO crops"):\n            lbl_path = lbl_dir / img_path.with_suffix(".txt").name\n\n            # load GT boxes + labels from YOLO txt\n            gt_boxes, gt_classes = [], []\n            if lbl_path.exists():\n                img_pil = Image.open(img_path)\n                W, H    = img_pil.size\n                for line in lbl_path.read_text().strip().splitlines():\n                    parts = line.split()\n                    if len(parts) < 5:\n                        continue\n                    cls_id      = int(parts[0])\n                    cx,cy,nw,nh = map(float, parts[1:5])\n                    x1=(cx-nw/2)*W; y1=(cy-nh/2)*H\n                    x2=(cx+nw/2)*W; y2=(cy+nh/2)*H\n                    gt_boxes.append([x1,y1,x2,y2])\n                    gt_classes.append(cls_id)\n            else:\n                img_pil = None\n\n            if not gt_boxes:\n                n_skipped += 1\n                continue\n\n            # run YOLO detector\n            result = detector.predict(\n                str(img_path), conf=conf, iou=0.6,\n                device=device, verbose=False\n            )[0]\n\n            if result.boxes is None or len(result.boxes) == 0:\n                n_skipped += 1\n                continue\n\n            det_boxes = result.boxes.xyxy.cpu().numpy()   # (N,4) pixel coords\n\n            gt_arr = np.array(gt_boxes, dtype=np.float32)\n            gt_cls = np.array(gt_classes, dtype=int)\n\n            # match each detected box → GT box via IoU\n            iou_mat = _box_iou_np(det_boxes, gt_arr)   # (N_det, N_gt)\n            matched_gt = set()\n\n            order = np.argsort(-det_boxes[:, 2] * det_boxes[:, 3])  # large first\n            for det_idx in order:\n                best_gt    = int(np.argmax(iou_mat[det_idx]))\n                best_iou   = float(iou_mat[det_idx, best_gt])\n                if best_iou < 0.5 or best_gt in matched_gt:\n                    continue\n                matched_gt.add(best_gt)\n                label = int(gt_cls[best_gt])\n\n                # crop + resize\n                x1,y1,x2,y2 = det_boxes[det_idx].astype(int)\n                W2, H2 = img_pil.size\n                x1=max(0,x1); y1=max(0,y1)\n                x2=min(W2,x2); y2=min(H2,y2)\n                if x2<=x1 or y2<=y1:\n                    continue\n                crop = img_pil.crop((x1,y1,x2,y2)).convert("RGB")\n                crop = crop.resize((CROP_SIZE, CROP_SIZE), Image.BILINEAR)\n\n                if cache_root:\n                    cls_cache = cache_root / str(label)\n                    cls_cache.mkdir(exist_ok=True)\n                    crop_path = cls_cache / f"{img_path.stem}_{det_idx}.jpg"\n                    crop.save(str(crop_path), quality=95)\n                    self.samples.append((crop_path, label))\n                else:\n                    # keep in memory as tensor\n                    t = transforms.ToTensor()(crop)\n                    self.samples.append((t, label))\n                n_matched += 1\n\n        print(f"  [{split}] {n_matched} matched crops  "\n              f"({n_skipped} images with no GT or no detections skipped)")\n\n    def __len__(self):\n        return len(self.samples)\n\n    def __getitem__(self, idx):\n        src, label = self.samples[idx]\n        if isinstance(src, Path):\n            img = read_image(str(src)).float() / 255.0\n            if img.shape[0] == 1:\n                img = img.repeat(3,1,1)\n        else:\n            img = src  # already a tensor\n        if self.transform:\n            img = self.transform(img)\n        return img, label\n\n\ndef _box_iou_np(a: np.ndarray, b: np.ndarray) -> np.ndarray:\n    """Compute IoU between two sets of xyxy boxes. Returns (N,M) matrix."""\n    ax1,ay1,ax2,ay2 = a[:,0],a[:,1],a[:,2],a[:,3]\n    bx1,by1,bx2,by2 = b[:,0],b[:,1],b[:,2],b[:,3]\n    ix1 = np.maximum(ax1[:,None], bx1[None,:])\n    iy1 = np.maximum(ay1[:,None], by1[None,:])\n    ix2 = np.minimum(ax2[:,None], bx2[None,:])\n    iy2 = np.minimum(ay2[:,None], by2[None,:])\n    inter = np.maximum(0,ix2-ix1) * np.maximum(0,iy2-iy1)\n    a_area = (ax2-ax1)*(ay2-ay1)\n    b_area = (bx2-bx1)*(by2-by1)\n    union  = a_area[:,None] + b_area[None,:] - inter\n    return inter / (union + 1e-7)\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# GT-CROP DATASET  (original mode — loads crops generated by preprocess.py)\n# ─────────────────────────────────────────────────────────────────────────────\n\nclass CropDataset(Dataset):\n    """\n    Loads 224×224 instance crops from\n    processed/{split}/path_B/crops/{class_idx}/.\n    """\n    def __init__(self, crops_root: Path, split: str, transform=None):\n        self.transform = transform\n        self.samples   = []\n        split_dir = crops_root / split / "path_B" / "crops"\n        assert split_dir.exists(), f"Crops dir not found: {split_dir}"\n        for cls_dir in sorted(split_dir.iterdir()):\n            if not cls_dir.is_dir():\n                continue\n            try:\n                cls_idx = int(cls_dir.name)\n            except ValueError:\n                continue\n            for img_path in cls_dir.glob("*.jpg"):\n                self.samples.append((img_path, cls_idx))\n        print(f"  [{split}] {len(self.samples)} GT crops across {NUM_CLASSES} classes")\n\n    def __len__(self):\n        return len(self.samples)\n\n    def __getitem__(self, idx):\n        img_path, label = self.samples[idx]\n        img = read_image(str(img_path)).float() / 255.0\n        if img.shape[0] == 1:\n            img = img.repeat(3, 1, 1)\n        if self.transform:\n            img = self.transform(img)\n        return img, label\n\n\ndef get_transforms(split: str):\n    if split == "train":\n        return transforms.Compose([\n            transforms.RandomHorizontalFlip(),\n            transforms.RandomVerticalFlip(p=0.1),\n            transforms.ColorJitter(\n                brightness=0.3, contrast=0.3,\n                saturation=0.3, hue=0.1,\n            ),\n            transforms.RandomRotation(30),\n            transforms.Normalize(\n                mean=[0.485, 0.456, 0.406],\n                std =[0.229, 0.224, 0.225],\n            ),\n        ])\n    return transforms.Compose([\n        transforms.Normalize(\n            mean=[0.485, 0.456, 0.406],\n            std =[0.229, 0.224, 0.225],\n        ),\n    ])\n\n\ndef get_class_weights(crops_root: Path) -> torch.Tensor:\n    weights_path = crops_root / "meta" / "class_weights.yaml"\n    if not weights_path.exists():\n        print("[warn] class_weights.yaml not found — using uniform weights")\n        return torch.ones(NUM_CLASSES)\n    with open(weights_path) as f:\n        data = yaml.safe_load(f)\n    cw = data.get("coarse_weights", {})\n    weights = torch.tensor(\n        [cw.get(cls, 1.0) for cls in COARSE_CLASSES], dtype=torch.float32)\n    print(f"Class weights: "\n          f"{ {c: round(float(w),3) for c,w in zip(COARSE_CLASSES, weights)} }")\n    return weights\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# MODEL BUILDER\n# ─────────────────────────────────────────────────────────────────────────────\n\ndef build_classifier(name: str) -> nn.Module:\n    model_str, pretrained = CLASSIFIER_REGISTRY[name]\n    model = timm.create_model(model_str, pretrained=pretrained,\n                               num_classes=NUM_CLASSES)\n    n = sum(p.numel() for p in model.parameters()) / 1e6\n    print(f"  Built {name} ({model_str})  pretrained={pretrained}  {n:.1f}M params")\n    return model\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# TRAINING LOOP\n# ─────────────────────────────────────────────────────────────────────────────\n\ndef train_classifier(\n    model, train_loader, val_loader,\n    epochs, lr, device, class_weights, patience, output_dir,\n) -> dict:\n    model = model.to(device)\n    class_weights = class_weights.to(device)\n\n    criterion = nn.CrossEntropyLoss(weight=class_weights)\n    optimizer = optim.AdamW(model.parameters(), lr=lr, weight_decay=5e-4)\n    scheduler = optim.lr_scheduler.CosineAnnealingLR(optimizer, T_max=epochs)\n\n    best_val_acc = 0.0\n    best_epoch   = 0\n    no_improve   = 0\n    history      = []\n\n    weights_dir = output_dir / "weights"\n    weights_dir.mkdir(parents=True, exist_ok=True)\n\n    for epoch in range(1, epochs + 1):\n        # ── train ─────────────────────────────────────────────────────────\n        model.train()\n        tr_loss = tr_correct = tr_total = 0\n        for imgs, labels in tqdm(train_loader,\n                                  desc=f"  Ep {epoch}/{epochs} train",\n                                  leave=False):\n            imgs, labels = imgs.to(device), labels.to(device)\n            optimizer.zero_grad()\n            out  = model(imgs)\n            loss = criterion(out, labels)\n            loss.backward()\n            optimizer.step()\n            tr_loss    += loss.item() * imgs.size(0)\n            tr_correct += (out.argmax(1) == labels).sum().item()\n            tr_total   += imgs.size(0)\n\n        scheduler.step()\n        tr_acc  = tr_correct / tr_total\n        tr_loss = tr_loss    / tr_total\n\n        # ── val ───────────────────────────────────────────────────────────\n        model.eval()\n        v_loss = v_correct = v_total = 0\n        all_preds, all_labels = [], []\n        with torch.no_grad():\n            for imgs, labels in tqdm(val_loader,\n                                      desc=f"  Ep {epoch}/{epochs} val",\n                                      leave=False):\n                imgs, labels = imgs.to(device), labels.to(device)\n                out    = model(imgs)\n                v_loss += criterion(out, labels).item() * imgs.size(0)\n                preds   = out.argmax(1)\n                v_correct += (preds == labels).sum().item()\n                v_total   += imgs.size(0)\n                all_preds.extend(preds.cpu().numpy())\n                all_labels.extend(labels.cpu().numpy())\n\n        v_acc  = v_correct / v_total\n        v_loss = v_loss    / v_total\n        v_f1   = f1_score(all_labels, all_preds,\n                          labels=list(range(NUM_CLASSES)),\n                          average="macro", zero_division=0)\n\n        print(f"  Ep {epoch:3d}/{epochs} | "\n              f"train loss={tr_loss:.4f} acc={tr_acc:.4f} | "\n              f"val loss={v_loss:.4f} acc={v_acc:.4f} f1={v_f1:.4f}")\n\n        history.append({\n            "epoch": epoch,\n            "train_loss": round(tr_loss,5), "train_acc": round(tr_acc,5),\n            "val_loss":   round(v_loss,5),  "val_acc":   round(v_acc,5),\n            "val_f1":     round(v_f1,5),\n            "lr": round(scheduler.get_last_lr()[0], 8),\n        })\n\n        if v_acc > best_val_acc:\n            best_val_acc = v_acc\n            best_epoch   = epoch\n            no_improve   = 0\n            torch.save(model.state_dict(), weights_dir / "best.pt")\n        else:\n            no_improve += 1\n            if no_improve >= patience:\n                print(f"  Early stopping at epoch {epoch} "\n                      f"(best epoch {best_epoch}, val_acc={best_val_acc:.4f})")\n                break\n\n    pd.DataFrame(history).to_csv(output_dir / "history.csv", index=False)\n    return {\n        "best_epoch":     best_epoch,\n        "best_val_acc":   round(best_val_acc, 5),\n        "stopped_early":  no_improve >= patience,\n        "epochs_trained": epoch,\n    }\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# TEST EVALUATION\n# ─────────────────────────────────────────────────────────────────────────────\n\ndef evaluate_on_test(model, test_loader, device, output_dir, clf_name) -> dict:\n    model.eval()\n    all_preds, all_labels, all_probs = [], [], []\n    with torch.no_grad():\n        for imgs, labels in tqdm(test_loader, desc="  Test"):\n            out   = model(imgs.to(device))\n            probs = torch.softmax(out, dim=1)\n            all_preds.extend(out.argmax(1).cpu().numpy())\n            all_labels.extend(labels.numpy())\n            all_probs.extend(probs.cpu().numpy())\n\n    all_preds  = np.array(all_preds)\n    all_labels = np.array(all_labels)\n    all_probs  = np.array(all_probs)\n    labels_r   = list(range(NUM_CLASSES))\n\n    per_class_ap = {}\n    for c in range(NUM_CLASSES):\n        gt_bin = (all_labels == c).astype(int)\n        per_class_ap[COARSE_CLASSES[c]] = (\n            round(float(average_precision_score(gt_bin, all_probs[:, c])), 5)\n            if gt_bin.sum() > 0 else 0.0\n        )\n\n    # latency\n    dummy = torch.zeros(1, 3, CROP_SIZE, CROP_SIZE).to(device)\n    for _ in range(10):\n        model(dummy)\n    t0 = time.perf_counter()\n    for _ in range(100):\n        model(dummy)\n    lat_ms = (time.perf_counter() - t0) / 100 * 1000\n\n    metrics = {\n        "classifier": clf_name,\n        "accuracy":   round(float((all_preds == all_labels).mean()), 5),\n        "precision":  round(float(precision_score(all_labels, all_preds,\n                             labels=labels_r, average="macro",\n                             zero_division=0)), 5),\n        "recall":     round(float(recall_score(all_labels, all_preds,\n                             labels=labels_r, average="macro",\n                             zero_division=0)), 5),\n        "f1":         round(float(f1_score(all_labels, all_preds,\n                             labels=labels_r, average="macro",\n                             zero_division=0)), 5),\n        "latency_ms": round(lat_ms, 3),\n    }\n    metrics.update({f"AP_{cls}": v for cls, v in per_class_ap.items()})\n\n    # confusion matrix\n    cm = confusion_matrix(all_labels, all_preds, labels=labels_r)\n    fig, ax = plt.subplots(figsize=(10, 8))\n    ConfusionMatrixDisplay(cm, display_labels=COARSE_CLASSES).plot(\n        ax=ax, colorbar=True, xticks_rotation=45)\n    ax.set_title(f"Path B — {clf_name} — test confusion matrix")\n    plt.tight_layout()\n    plt.savefig(output_dir / f"confusion_matrix_{clf_name}.png", dpi=150)\n    plt.close()\n\n    with open(output_dir / "metrics.json", "w") as f:\n        json.dump(metrics, f, indent=2)\n\n    print(f"\\n  [{clf_name}]  accuracy={metrics[\'accuracy\']:.4f}  "\n          f"f1={metrics[\'f1\']:.4f}  latency={lat_ms:.2f}ms")\n    return metrics\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# SUMMARY\n# ─────────────────────────────────────────────────────────────────────────────\n\ndef print_summary(output_dir: Path):\n    records = []\n    for p in sorted(output_dir.glob("*/metrics.json")):\n        with open(p) as f:\n            m = json.load(f)\n        m["classifier"] = p.parent.name\n        records.append(m)\n    if not records:\n        print("No metrics.json files found.")\n        return\n    df = pd.DataFrame(records).set_index("classifier")\n    df = df.sort_values("accuracy", ascending=False)\n    print("\\n" + "="*70)\n    print("PATH B  —  CLASSIFIER BENCHMARK SUMMARY")\n    print("="*70)\n    print(df.to_string(float_format="{:.4f}".format))\n    print("="*70)\n\n\n# ─────────────────────────────────────────────────────────────────────────────\n# CLI\n# ─────────────────────────────────────────────────────────────────────────────\n\ndef parse_args():\n    p = argparse.ArgumentParser(description="Path B: two-stage detect+classify")\n    p.add_argument("--detector_weights", type=Path, required=True,\n                   help="best.pt from best Path A model (frozen detector)")\n    p.add_argument("--crops_dir",        type=Path, required=True,\n                   help="processed_4cls root dir")\n    p.add_argument("--output",           type=Path,\n                   default=Path("runs/path_B"))\n    p.add_argument("--classifiers",      nargs="+",\n                   default=list(CLASSIFIER_REGISTRY.keys()),\n                   choices=list(CLASSIFIER_REGISTRY.keys()))\n    p.add_argument("--epochs",           type=int,   default=50)\n    p.add_argument("--batch",            type=int,   default=32)\n    p.add_argument("--lr",               type=float, default=1e-4)\n    p.add_argument("--patience",         type=int,   default=10)\n    p.add_argument("--device",           type=str,   default="0")\n    p.add_argument("--mlflow_uri",       type=str,   default="./mlruns")\n    p.add_argument("--summarize",        action="store_true")\n    # ── YOLO-crop mode flags ───────────────────────────────────────────────\n    p.add_argument("--use_yolo_crops",   action="store_true",\n                   help="Extract crops from YOLO detector instead of GT crops")\n    p.add_argument("--det_conf",         type=float, default=0.25,\n                   help="YOLO detection confidence threshold for crop extraction")\n    p.add_argument("--crop_cache_dir",   type=Path,  default=None,\n                   help="Cache directory for YOLO-extracted crops")\n    return p.parse_args()\n\n\nif __name__ == "__main__":\n    args = parse_args()\n\n    if args.summarize:\n        print_summary(args.output)\n        raise SystemExit(0)\n\n    device = torch.device(\n        f"cuda:{args.device}" if torch.cuda.is_available() else "cpu")\n    print(f"Device : {device}")\n    if torch.cuda.is_available():\n        dev = torch.cuda.get_device_properties(int(args.device))\n        print(f"GPU    : {dev.name}  VRAM: {dev.total_memory/1e9:.1f}GB")\n\n    mlflow.set_tracking_uri(args.mlflow_uri)\n    class_weights = get_class_weights(args.crops_dir)\n    args.output.mkdir(parents=True, exist_ok=True)\n\n    # ── build datasets ────────────────────────────────────────────────────\n    if args.use_yolo_crops:\n        print("\\n  Mode: YOLO on-the-fly crop extraction")\n        from ultralytics import YOLO as _YOLO\n        _detector = _YOLO(str(args.detector_weights))\n        _det_dev  = args.device\n\n        train_ds = YOLOCropDataset(\n            args.crops_dir, "train",\n            detector  = _detector,\n            device    = _det_dev,\n            conf      = args.det_conf,\n            transform = get_transforms("train"),\n            cache_dir = args.crop_cache_dir,\n        )\n        val_ds = YOLOCropDataset(\n            args.crops_dir, "val",\n            detector  = _detector,\n            device    = _det_dev,\n            conf      = args.det_conf,\n            transform = get_transforms("val"),\n            cache_dir = args.crop_cache_dir,\n        )\n        test_ds = YOLOCropDataset(\n            args.crops_dir, "test",\n            detector  = _detector,\n            device    = _det_dev,\n            conf      = args.det_conf,\n            transform = get_transforms("test"),\n            cache_dir = args.crop_cache_dir,\n        )\n    else:\n        print("\\n  Mode: loading pre-generated GT crops from disk")\n        train_ds = CropDataset(args.crops_dir, "train",\n                                transform=get_transforms("train"))\n        val_ds   = CropDataset(args.crops_dir, "val",\n                                transform=get_transforms("val"))\n        test_ds  = CropDataset(args.crops_dir, "test",\n                                transform=get_transforms("test"))\n\n    train_loader = DataLoader(train_ds, batch_size=args.batch,\n                              shuffle=True,  num_workers=4, pin_memory=True)\n    val_loader   = DataLoader(val_ds,   batch_size=args.batch,\n                              shuffle=False, num_workers=4, pin_memory=True)\n    test_loader  = DataLoader(test_ds,  batch_size=args.batch,\n                              shuffle=False, num_workers=4, pin_memory=True)\n\n    all_metrics = {}\n\n    for clf_name in args.classifiers:\n        print(f"\\n{\'─\'*60}")\n        print(f"  Classifier : {clf_name}")\n        print(f"{\'─\'*60}")\n\n        run_dir = args.output / clf_name\n        run_dir.mkdir(parents=True, exist_ok=True)\n\n        model = build_classifier(clf_name)\n\n        train_info = train_classifier(\n            model=model, train_loader=train_loader,\n            val_loader=val_loader, epochs=args.epochs,\n            lr=args.lr, device=device,\n            class_weights=class_weights, patience=args.patience,\n            output_dir=run_dir,\n        )\n\n        # load best weights for test\n        model.load_state_dict(\n            torch.load(run_dir / "weights" / "best.pt", map_location=device))\n\n        metrics = evaluate_on_test(\n            model=model, test_loader=test_loader,\n            device=device, output_dir=run_dir,\n            clf_name=clf_name,\n        )\n        metrics.update(train_info)\n        all_metrics[clf_name] = metrics\n\n        mlflow.set_experiment("litter_path_B")\n        with mlflow.start_run(run_name=clf_name):\n            mlflow.log_params({\n                "classifier":    clf_name,\n                "epochs":        args.epochs,\n                "batch":         args.batch,\n                "lr":            args.lr,\n                "patience":      args.patience,\n                "use_yolo_crops":args.use_yolo_crops,\n                "det_conf":      args.det_conf,\n                "device":        args.device,\n            })\n            mlflow.log_metrics(\n                {k: v for k, v in metrics.items() if isinstance(v, (int, float))})\n            best_pt = run_dir / "weights" / "best.pt"\n            if best_pt.exists():\n                mlflow.log_artifact(str(best_pt), "weights")\n\n        print(f"\\n  [{clf_name}]  best_epoch={train_info[\'best_epoch\']}  "\n              f"val_acc={train_info[\'best_val_acc\']:.4f}  "\n              f"test_acc={metrics[\'accuracy\']:.4f}  "\n              f"f1={metrics[\'f1\']:.4f}")\n\n        del model\n        torch.cuda.empty_cache()\n\n    print_summary(args.output)\n'

_CASCADE_CODE = '"""\ntrain_path_B_cascade.py — Path B cascade classifier: coarse -> fine.\n\nPipeline:\n  Stage 1: frozen YOLO detector supplies boxes (same as old Path B).\n  Stage 2: coarse crop classifier predicts material: plastic/paper/metal/glass/other.\n  Stage 3: one fine classifier per coarse material refines into subclasses inside that material.\n\nTraining uses GT crops from preprocess_cascade.py because fine labels are known there.\nEvaluation with detector boxes is handled by evaluate_path_B_cascade_combined.py.\n\nUsage:\n  python train_path_B_cascade.py \\\n    --crops_dir /workspace/processed_5cls \\\n    --output /workspace/runs/path_B_cascade \\\n    --backbone resnet50 \\\n    --epochs 30 --batch 32 --device 0\n"""\n\nimport argparse\nimport json\nimport time\nimport shutil\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\nimport torch\nimport torch.nn as nn\nimport torch.optim as optim\nimport yaml\nfrom sklearn.metrics import accuracy_score, f1_score, precision_score, recall_score, confusion_matrix\nfrom torch.utils.data import DataLoader, Dataset\nfrom torchvision import transforms\nfrom torchvision.io import read_image\nfrom tqdm import tqdm\nimport timm\nimport matplotlib.pyplot as plt\nfrom sklearn.metrics import ConfusionMatrixDisplay\n\nCOARSE_CLASSES = ["plastic", "paper", "metal", "glass", "other"]\nCROP_SIZE = 224\n\nBACKBONES = {\n    "resnet50": ("resnet50.a1_in1k", True),\n    "vit_b16_scratch": ("vit_base_patch16_224", False),\n    "vit_b16_imagenet": ("vit_base_patch16_224.augreg_in21k_ft_in1k", True),\n}\n\n\ndef get_transforms(split: str):\n    if split == "train":\n        return transforms.Compose([\n            transforms.RandomHorizontalFlip(),\n            transforms.RandomVerticalFlip(p=0.1),\n            transforms.ColorJitter(brightness=0.3, contrast=0.3, saturation=0.3, hue=0.1),\n            transforms.RandomRotation(30),\n            transforms.Normalize([0.485, 0.456, 0.406], [0.229, 0.224, 0.225]),\n        ])\n    return transforms.Compose([\n        transforms.Normalize([0.485, 0.456, 0.406], [0.229, 0.224, 0.225]),\n    ])\n\n\nclass CropIndexDataset(Dataset):\n    def __init__(self, data_root: Path, split: str, target: str, parent: str | None = None, fine_subset: list[int] | None = None, transform=None):\n        self.data_root = Path(data_root)\n        self.transform = transform\n        self.samples = []\n        csv_path = self.data_root / split / "path_B" / "crop_index.csv"\n        if not csv_path.exists():\n            raise FileNotFoundError(f"Missing crop index: {csv_path}. Run preprocess_cascade.py first.")\n        df = pd.read_csv(csv_path)\n        if parent is not None:\n            df = df[df["coarse_label"] == parent]\n        if fine_subset is not None:\n            df = df[df["fine_idx"].isin(fine_subset)]\n        if df.empty:\n            print(f"  [{split}] empty dataset target={target} parent={parent}")\n            return\n        if target == "coarse":\n            for _, r in df.iterrows():\n                self.samples.append((self.data_root / str(r["crop_path"]), int(r["coarse_idx"])))\n            self.class_ids = list(range(len(COARSE_CLASSES)))\n            self.global_to_local = {i: i for i in self.class_ids}\n        elif target == "fine":\n            class_ids = sorted(int(x) for x in df["fine_idx"].unique())\n            self.class_ids = class_ids\n            self.global_to_local = {gid: i for i, gid in enumerate(class_ids)}\n            for _, r in df.iterrows():\n                gid = int(r["fine_idx"])\n                self.samples.append((self.data_root / str(r["fine_crop_path"]), self.global_to_local[gid]))\n        else:\n            raise ValueError("target must be \'coarse\' or \'fine\'")\n        print(f"  [{split}] target={target} parent={parent} crops={len(self.samples)} classes={len(self.class_ids)}")\n\n    def __len__(self):\n        return len(self.samples)\n\n    def __getitem__(self, idx):\n        img_path, label = self.samples[idx]\n        img = read_image(str(img_path)).float() / 255.0\n        if img.shape[0] == 1:\n            img = img.repeat(3, 1, 1)\n        if img.shape[0] == 4:\n            img = img[:3]\n        if self.transform:\n            img = self.transform(img)\n        return img, label\n\n\ndef load_maps(data_root: Path):\n    path = data_root / "meta" / "fine_class_map.json"\n    if not path.exists():\n        raise FileNotFoundError(f"Missing {path}. Run preprocess_cascade.py first.")\n    data = json.loads(path.read_text())\n    return data\n\n\ndef build_model(backbone: str, num_classes: int) -> nn.Module:\n    model_name, pretrained = BACKBONES[backbone]\n    model = timm.create_model(model_name, pretrained=pretrained, num_classes=num_classes)\n    n = sum(p.numel() for p in model.parameters()) / 1e6\n    print(f"  Built {backbone} ({model_name}) num_classes={num_classes} pretrained={pretrained} params={n:.1f}M")\n    return model\n\n\ndef class_weights_from_dataset(ds: CropIndexDataset, num_classes: int) -> torch.Tensor:\n    if len(ds) == 0:\n        return torch.ones(num_classes)\n    counts = np.zeros(num_classes, dtype=np.float32)\n    for _, label in ds.samples:\n        counts[label] += 1\n    counts[counts == 0] = 1\n    freq = counts / counts.sum()\n    weights = 1.0 / np.sqrt(freq)\n    weights = weights / weights.mean()\n    return torch.tensor(weights, dtype=torch.float32)\n\n\ndef train_one(model, train_loader, val_loader, epochs, lr, device, patience, output_dir, class_weights):\n    output_dir.mkdir(parents=True, exist_ok=True)\n    weights_dir = output_dir / "weights"\n    weights_dir.mkdir(exist_ok=True)\n    model = model.to(device)\n    criterion = nn.CrossEntropyLoss(weight=class_weights.to(device))\n    optimizer = optim.AdamW(model.parameters(), lr=lr, weight_decay=5e-4)\n    scheduler = optim.lr_scheduler.CosineAnnealingLR(optimizer, T_max=max(1, epochs))\n    best_f1 = -1.0\n    best_epoch = 0\n    no_improve = 0\n    history = []\n\n    for epoch in range(1, epochs + 1):\n        model.train()\n        tr_loss = tr_total = tr_correct = 0\n        for imgs, labels in tqdm(train_loader, desc=f"  epoch {epoch}/{epochs} train", leave=False):\n            imgs, labels = imgs.to(device), labels.to(device)\n            optimizer.zero_grad()\n            logits = model(imgs)\n            loss = criterion(logits, labels)\n            loss.backward()\n            optimizer.step()\n            tr_loss += loss.item() * imgs.size(0)\n            tr_correct += (logits.argmax(1) == labels).sum().item()\n            tr_total += imgs.size(0)\n        scheduler.step()\n\n        model.eval()\n        val_loss = val_total = val_correct = 0\n        y_true, y_pred = [], []\n        with torch.no_grad():\n            for imgs, labels in tqdm(val_loader, desc=f"  epoch {epoch}/{epochs} val", leave=False):\n                imgs, labels = imgs.to(device), labels.to(device)\n                logits = model(imgs)\n                loss = criterion(logits, labels)\n                preds = logits.argmax(1)\n                val_loss += loss.item() * imgs.size(0)\n                val_correct += (preds == labels).sum().item()\n                val_total += imgs.size(0)\n                y_true.extend(labels.cpu().numpy())\n                y_pred.extend(preds.cpu().numpy())\n\n        tr_acc = tr_correct / max(1, tr_total)\n        val_acc = val_correct / max(1, val_total)\n        val_f1 = f1_score(y_true, y_pred, average="macro", zero_division=0) if y_true else 0.0\n        row = {\n            "epoch": epoch,\n            "train_loss": tr_loss / max(1, tr_total),\n            "train_acc": tr_acc,\n            "val_loss": val_loss / max(1, val_total),\n            "val_acc": val_acc,\n            "val_f1": val_f1,\n            "lr": scheduler.get_last_lr()[0],\n        }\n        history.append(row)\n        print(f"  ep={epoch:03d} train_acc={tr_acc:.4f} val_acc={val_acc:.4f} val_f1={val_f1:.4f}")\n\n        if val_f1 > best_f1:\n            best_f1 = val_f1\n            best_epoch = epoch\n            no_improve = 0\n            torch.save(model.state_dict(), weights_dir / "best.pt")\n        else:\n            no_improve += 1\n            if no_improve >= patience:\n                print(f"  early stopping at epoch {epoch}; best_epoch={best_epoch} best_val_f1={best_f1:.4f}")\n                break\n\n    pd.DataFrame(history).to_csv(output_dir / "history.csv", index=False)\n    return {"best_epoch": best_epoch, "best_val_f1": round(best_f1, 5), "epochs_trained": epoch}\n\n\ndef evaluate_classifier(model, loader, device, class_names, output_dir, title):\n    model.eval()\n    y_true, y_pred = [], []\n    t0 = time.perf_counter()\n    with torch.no_grad():\n        for imgs, labels in tqdm(loader, desc=f"  test {title}"):\n            logits = model(imgs.to(device))\n            y_pred.extend(logits.argmax(1).cpu().numpy())\n            y_true.extend(labels.numpy())\n    elapsed = time.perf_counter() - t0\n    labels = list(range(len(class_names)))\n    metrics = {\n        "accuracy": round(float(accuracy_score(y_true, y_pred)), 5) if y_true else 0.0,\n        "precision_macro": round(float(precision_score(y_true, y_pred, labels=labels, average="macro", zero_division=0)), 5) if y_true else 0.0,\n        "recall_macro": round(float(recall_score(y_true, y_pred, labels=labels, average="macro", zero_division=0)), 5) if y_true else 0.0,\n        "f1_macro": round(float(f1_score(y_true, y_pred, labels=labels, average="macro", zero_division=0)), 5) if y_true else 0.0,\n        "n_samples": len(y_true),\n        "fps_crops": round(len(y_true) / max(elapsed, 1e-9), 2),\n    }\n    (output_dir / "metrics.json").write_text(json.dumps(metrics, indent=2))\n    if y_true and len(class_names) <= 40:\n        cm = confusion_matrix(y_true, y_pred, labels=labels)\n        fig, ax = plt.subplots(figsize=(max(8, len(class_names) * 0.6), max(6, len(class_names) * 0.5)))\n        ConfusionMatrixDisplay(cm, display_labels=class_names).plot(ax=ax, colorbar=True, xticks_rotation=45)\n        ax.set_title(title)\n        plt.tight_layout()\n        fig.savefig(output_dir / "confusion_matrix.png", dpi=150)\n        plt.close(fig)\n    print(f"  {title}: acc={metrics[\'accuracy\']:.4f} f1={metrics[\'f1_macro\']:.4f}")\n    return metrics\n\n\ndef save_model_metadata(output_dir: Path, kind: str, backbone: str, class_ids: list[int], class_names: list[str], extra: dict | None = None):\n    meta = {"kind": kind, "backbone": backbone, "class_ids": class_ids, "class_names": class_names}\n    if extra:\n        meta.update(extra)\n    (output_dir / "model_meta.json").write_text(json.dumps(meta, indent=2))\n\n\ndef make_loader(ds, batch, shuffle):\n    return DataLoader(ds, batch_size=batch, shuffle=shuffle, num_workers=4, pin_memory=torch.cuda.is_available())\n\n\n\n\ndef best_weight_path(run_dir: Path) -> Path:\n    return run_dir / "weights" / "best.pt"\n\n\ndef load_matching_weights(model: nn.Module, weights_path: Path, device, *, strict: bool = False) -> None:\n    """\n    Loads weights into a model. With strict=False, layers with incompatible\n    shapes are skipped, which is useful when reusing an old classifier backbone\n    but changing the number of output classes.\n    """\n    weights_path = Path(weights_path)\n    if not weights_path.exists():\n        raise FileNotFoundError(f"Weights not found: {weights_path}")\n    state = torch.load(weights_path, map_location=device)\n    if isinstance(state, dict) and "state_dict" in state:\n        state = state["state_dict"]\n    if strict:\n        model.load_state_dict(state, strict=True)\n        print(f"  Loaded strict weights: {weights_path}")\n        return\n    current = model.state_dict()\n    compatible = {}\n    skipped = []\n    for k, v in state.items():\n        key = k.replace("module.", "")\n        if key in current and current[key].shape == v.shape:\n            compatible[key] = v\n        else:\n            skipped.append(k)\n    current.update(compatible)\n    model.load_state_dict(current, strict=False)\n    print(f"  Loaded {len(compatible)} compatible tensors from {weights_path}")\n    if skipped:\n        print(f"  Skipped {len(skipped)} incompatible tensors, usually classifier head layers")\n\n\ndef copy_weights_file(src: Path, dst: Path) -> bool:\n    src = Path(src)\n    if not src.exists():\n        print(f"  [warn] source weights not found: {src}")\n        return False\n    dst.parent.mkdir(parents=True, exist_ok=True)\n    shutil.copy2(src, dst)\n    print(f"  Registered existing weights: {src} -> {dst}")\n    return True\n\n\ndef maybe_copy_metadata(src_run_dir: Path, dst_run_dir: Path) -> None:\n    for name in ["model_meta.json", "metrics.json", "history.csv", "confusion_matrix.png"]:\n        src = src_run_dir / name\n        if src.exists():\n            dst = dst_run_dir / name\n            dst.parent.mkdir(parents=True, exist_ok=True)\n            shutil.copy2(src, dst)\n\n\ndef resolve_fine_parent_dir(fine_dir: Path, parent: str) -> Path | None:\n    """Accepts either <root>/fine/<parent> or <root>/<parent>."""\n    if fine_dir is None:\n        return None\n    fine_dir = Path(fine_dir)\n    candidates = [fine_dir / parent, fine_dir / "fine" / parent]\n    for c in candidates:\n        if best_weight_path(c).exists():\n            return c\n    return None\n\n\ndef ensure_coarse_available(args) -> bool:\n    """Makes args.output/coarse/weights/best.pt available when skipping/reusing."""\n    run_dir = args.output / "coarse"\n    dst = best_weight_path(run_dir)\n    if dst.exists():\n        print(f"  Coarse weights already available: {dst}")\n        return True\n    if args.coarse_weights:\n        return copy_weights_file(args.coarse_weights, dst)\n    print(f"  [warn] coarse weights missing: {dst}")\n    print("  Provide --coarse_weights or train coarse before evaluation.")\n    return False\n\n\ndef ensure_fine_available(args, parent: str) -> bool:\n    """Makes args.output/fine/<parent>/weights/best.pt available from --fine_dir."""\n    run_dir = args.output / "fine" / parent\n    dst = best_weight_path(run_dir)\n    if dst.exists():\n        print(f"  Fine weights already available for {parent}: {dst}")\n        return True\n    src_run_dir = resolve_fine_parent_dir(args.fine_dir, parent) if args.fine_dir else None\n    if src_run_dir is None:\n        print(f"  [warn] fine weights missing for {parent}: {dst}")\n        return False\n    copied = copy_weights_file(best_weight_path(src_run_dir), dst)\n    if copied:\n        maybe_copy_metadata(src_run_dir, run_dir)\n    return copied\n\ndef train_coarse(args, device):\n    run_dir = args.output / "coarse"\n    existing_best = best_weight_path(run_dir)\n\n    if args.skip_coarse:\n        print("\\n[skip] coarse stage requested via --skip_coarse")\n        ensure_coarse_available(args)\n        return {}\n\n    train_ds = CropIndexDataset(args.crops_dir, "train", target="coarse", transform=get_transforms("train"))\n    val_ds = CropIndexDataset(args.crops_dir, "val", target="coarse", transform=get_transforms("val"))\n    test_ds = CropIndexDataset(args.crops_dir, "test", target="coarse", transform=get_transforms("test"))\n\n    model = build_model(args.backbone, len(COARSE_CLASSES))\n\n    if args.resume and existing_best.exists():\n        print(f"\\n[resume] coarse already trained; skipping training and loading {existing_best}")\n        load_matching_weights(model, existing_best, device, strict=True)\n        metrics = evaluate_classifier(model.to(device), make_loader(test_ds, args.batch, False), device, COARSE_CLASSES, run_dir, "Path B cascade — coarse classifier")\n        save_model_metadata(run_dir, "coarse", args.backbone, list(range(len(COARSE_CLASSES))), COARSE_CLASSES)\n        return metrics\n\n    if args.coarse_weights:\n        print(f"\\nInitializing coarse model from --coarse_weights={args.coarse_weights}")\n        load_matching_weights(model, args.coarse_weights, device, strict=False)\n\n    info = train_one(\n        model,\n        make_loader(train_ds, args.batch, True),\n        make_loader(val_ds, args.batch, False),\n        args.epochs,\n        args.lr,\n        device,\n        args.patience,\n        run_dir,\n        class_weights_from_dataset(train_ds, len(COARSE_CLASSES)),\n    )\n    model.load_state_dict(torch.load(existing_best, map_location=device))\n    metrics = evaluate_classifier(model.to(device), make_loader(test_ds, args.batch, False), device, COARSE_CLASSES, run_dir, "Path B cascade — coarse classifier")\n    metrics.update(info)\n    (run_dir / "metrics.json").write_text(json.dumps(metrics, indent=2))\n    save_model_metadata(run_dir, "coarse", args.backbone, list(range(len(COARSE_CLASSES))), COARSE_CLASSES)\n    return metrics\n\ndef train_fine(args, device, maps):\n    fine_classes = maps["fine_classes"]\n    coarse_to_fine = {c: [int(i) for i in ids] for c, ids in maps["coarse_to_fine_indices"].items()}\n    all_metrics = {}\n\n    if args.skip_fine:\n        print("\\n[skip] fine stage requested via --skip_fine")\n        for parent in COARSE_CLASSES:\n            ensure_fine_available(args, parent)\n        return all_metrics\n\n    for parent in COARSE_CLASSES:\n        fine_ids = sorted(coarse_to_fine.get(parent, []))\n        if len(fine_ids) < 2:\n            print(f"\\n[skip] fine classifier for {parent}: only {len(fine_ids)} fine class")\n            continue\n\n        run_dir = args.output / "fine" / parent\n        existing_best = best_weight_path(run_dir)\n        src_run_dir = resolve_fine_parent_dir(args.fine_dir, parent) if args.fine_dir else None\n\n        print(f"\\n{\'─\'*60}\\nFine classifier parent={parent} classes={len(fine_ids)}\\n{\'─\'*60}")\n\n        train_ds = CropIndexDataset(args.crops_dir, "train", target="fine", parent=parent, fine_subset=fine_ids, transform=get_transforms("train"))\n        val_ds = CropIndexDataset(args.crops_dir, "val", target="fine", parent=parent, fine_subset=fine_ids, transform=get_transforms("val"))\n        test_ds = CropIndexDataset(args.crops_dir, "test", target="fine", parent=parent, fine_subset=fine_ids, transform=get_transforms("test"))\n        if len(train_ds) == 0 or len(val_ds) == 0 or len(test_ds) == 0:\n            print(f"[skip] {parent}: empty train/val/test after filtering")\n            continue\n\n        class_names = [fine_classes[i] for i in train_ds.class_ids]\n        model = build_model(args.backbone, len(train_ds.class_ids))\n\n        if args.resume and existing_best.exists():\n            print(f"[resume] fine {parent} already trained; skipping training and loading {existing_best}")\n            load_matching_weights(model, existing_best, device, strict=True)\n            metrics = evaluate_classifier(model.to(device), make_loader(test_ds, args.batch, False), device, class_names, run_dir, f"Path B cascade — fine {parent}")\n            save_model_metadata(run_dir, "fine", args.backbone, train_ds.class_ids, class_names, {"parent_coarse": parent, "parent_coarse_idx": COARSE_CLASSES.index(parent)})\n            all_metrics[parent] = metrics\n            del model\n            torch.cuda.empty_cache()\n            continue\n\n        if src_run_dir is not None and not existing_best.exists():\n            print(f"Initializing fine {parent} from --fine_dir={src_run_dir}")\n            load_matching_weights(model, best_weight_path(src_run_dir), device, strict=False)\n\n        info = train_one(\n            model,\n            make_loader(train_ds, args.batch, True),\n            make_loader(val_ds, args.batch, False),\n            args.epochs,\n            args.lr,\n            device,\n            args.patience,\n            run_dir,\n            class_weights_from_dataset(train_ds, len(train_ds.class_ids)),\n        )\n        model.load_state_dict(torch.load(existing_best, map_location=device))\n        metrics = evaluate_classifier(model.to(device), make_loader(test_ds, args.batch, False), device, class_names, run_dir, f"Path B cascade — fine {parent}")\n        metrics.update(info)\n        (run_dir / "metrics.json").write_text(json.dumps(metrics, indent=2))\n        save_model_metadata(run_dir, "fine", args.backbone, train_ds.class_ids, class_names, {"parent_coarse": parent, "parent_coarse_idx": COARSE_CLASSES.index(parent)})\n        all_metrics[parent] = metrics\n        del model\n        torch.cuda.empty_cache()\n    return all_metrics\n\ndef summarize(output: Path):\n    records = []\n    for p in output.rglob("metrics.json"):\n        rel = p.parent.relative_to(output)\n        m = json.loads(p.read_text())\n        m["model"] = str(rel)\n        records.append(m)\n    if not records:\n        print("No metrics found.")\n        return\n    df = pd.DataFrame(records).set_index("model").sort_values("f1_macro", ascending=False)\n    print("\\nPATH B CASCADE SUMMARY")\n    print(df.to_string(float_format="{:.4f}".format))\n\n\ndef parse_args():\n    p = argparse.ArgumentParser(description="Train Path B coarse->fine cascade classifiers")\n    p.add_argument("--crops_dir", type=Path, required=True, help="processed root created by preprocess_cascade.py")\n    p.add_argument("--output", type=Path, default=Path("runs/path_B_cascade"))\n    p.add_argument("--backbone", choices=list(BACKBONES.keys()), default="resnet50")\n    p.add_argument("--stages", nargs="+", choices=["coarse", "fine", "all"], default=["all"])\n    p.add_argument("--epochs", type=int, default=30)\n    p.add_argument("--batch", type=int, default=32)\n    p.add_argument("--lr", type=float, default=1e-4)\n    p.add_argument("--patience", type=int, default=8)\n    p.add_argument("--device", type=str, default="0")\n    p.add_argument("--summarize", action="store_true")\n    p.add_argument("--skip_coarse", action="store_true", help="Do not train the coarse classifier. Optionally register --coarse_weights into output/coarse/weights/best.pt.")\n    p.add_argument("--skip_fine", action="store_true", help="Do not train fine classifiers. Optionally register weights from --fine_dir.")\n    p.add_argument("--coarse_weights", type=Path, default=None, help="Existing coarse best.pt to initialize or register when --skip_coarse is used.")\n    p.add_argument("--fine_dir", type=Path, default=None, help="Existing fine classifiers root. Accepts either <root>/fine/<parent>/weights/best.pt or <root>/<parent>/weights/best.pt.")\n    p.add_argument("--resume", action="store_true", help="Skip training stages whose output weights already exist, then evaluate/summarize them.")\n    return p.parse_args()\n\n\nif __name__ == "__main__":\n    args = parse_args()\n    args.output.mkdir(parents=True, exist_ok=True)\n    if args.summarize:\n        summarize(args.output)\n        raise SystemExit(0)\n\n    device = torch.device(f"cuda:{args.device}" if args.device.isdigit() and torch.cuda.is_available() else "cpu")\n    print(f"Device: {device}")\n    maps = load_maps(args.crops_dir)\n    stages = {"coarse", "fine"} if "all" in args.stages else set(args.stages)\n\n    if "coarse" in stages:\n        print("\\nTraining coarse classifier")\n        train_coarse(args, device)\n    if "fine" in stages:\n        print("\\nTraining fine classifiers")\n        train_fine(args, device, maps)\n    summarize(args.output)\n'

